@Finsupp.prod_eq_zero_iff : ∀ {α : Type u_1} {ι : Type u_2} {β : Type u_3} [inst : Zero α]
  [inst_1 : CommMonoidWithZero β] [Nontrivial β] [NoZeroDivisors β] {f : ι →₀ α} {g : ι → α → β},
  f.prod g = 0 ↔ ∃ i ∈ f.support, g i (f i) = 0

@Finsupp.prod_ne_zero_iff : ∀ {α : Type u_1} {ι : Type u_2} {β : Type u_3} [inst : Zero α]
  [inst_1 : CommMonoidWithZero β] [Nontrivial β] [NoZeroDivisors β] {f : ι →₀ α} {g : ι → α → β},
  f.prod g ≠ 0 ↔ ∀ i ∈ f.support, g i (f i) ≠ 0
